(85, '2026-08-28', 'Loose watery dung, calf weak, eyes sunken, not suckling well', 'Calf diarrhoea (scours)', 'Oral rehydration solution, antibiotic as advised, small frequent milk feeds, probiotic', NULL, true),
(12, '2026-08-31', 'High fever, swollen glands near the shoulder, no appetite, watery eyes, milk dropped', 'Theileriosis (tick fever), blood smear positive', 'Buparvaquone injection, antibiotic, fluids and liver tonic, tick spray on animal and shed', 'Dr. K. Srinivas', true),
