(115, '2026-09-07', 'No heat signs seen 131 days after calving', 'Post-calving anestrus (no heat), poor body condition suspected', 'Mineral mixture and green fodder added, deworming, hormone treatment advised if no heat in 3 weeks', 'Dr. Rajesh Malik', true),
